const fs = require('fs');
const crypto = require('crypto');

const passage = fs.readFileSync('editor-guide.md', 'utf8');
const hash = crypto.createHash('sha256').update(passage, 'utf8').digest('hex');
console.log('hash:', hash);

if (!fs.existsSync('.session')) fs.mkdirSync('.session');

const taskClock = {
  startedAt: '2026-10-20T18:30:18.635627Z',
  deadlineAt: '2026-10-20T18:35:18.635627Z',
  basis: 'host_provided',
  sourceRef: 'local:request-origin.json'
};
fs.writeFileSync('.session/task-clock.json', JSON.stringify(taskClock, null, 2), 'utf8');

const task = {
  schemaVersion: '0.1',
  taskId: 'task-saved-published-explanation',
  goal: '編集画面のSavedとPublishedの意味およびチームページ閲覧者への見え方を説明する',
  mode: 'explain',
  successCriteria: [
    'Savedと表示された変更がチームページ閲覧者に見えるかを根拠付きで明記する',
    'PublishedとSavedの関係を整理して説明する'
  ],
  capabilities: ['document_reading', 'explanation'],
  reflectionRequired: true,
  evidence: [
    {
      id: 'evidence-editor-guide',
      kind: 'document',
      locator: 'file:editor-guide.md',
      sourceGroup: 'draft-editor-doc',
      retrievedAt: '2026-10-20T18:32:00.000Z',
      version: null,
      scope: 'sample-team-editor-status',
      passage: passage,
      contentHash: hash,
      validity: 'current'
    }
  ],
  budget: {
    maxRounds: 10,
    maxModelCalls: 10,
    maxToolCalls: 10,
    maxElapsedMs: 180000,
    maxInputChars: 100000,
    maxOutputTokensPerCall: 4000,
    maxCostYen: 0
  }
};
fs.writeFileSync('.session/task.json', JSON.stringify(task, null, 2), 'utf8');
console.log('created task.json and task-clock.json');
"
