$ node -e "
const fs = require('fs');

const context = JSON.parse(fs.readFileSync('.session/context.json', 'utf8'));

const proposal = {
  claims: [
    {
      id: 'claim-saved-draft-only',
      role: 'answer_claim',
      text: '編集画面でSavedと表示された変更は下書きリビジョンとしてワークスペースに保存された状態であり、チームページ閲覧者には見えない。',
      scope: 'sample-team-editor-status'
    },
    {
      id: 'claim-published-copy-visible',
      role: 'answer_claim',
      text: 'Publishedは保存済みリビジョンから公開コピーを作成し、チームページ上で利用可能にする操作である。',
      scope: 'sample-team-editor-status'
    },
    {
      id: 'claim-further-save-no-overwrite',
      role: 'answer_claim',
      text: '公開後にさらに保存（Save）を行っても、既存の公開コピーは自動的には置き換わらない。',
      scope: 'sample-team-editor-status'
    },
    {
      id: 'claim-preview-default',
      role: 'observation',
      text: 'エディタのプレビューはデフォルトで直近に公開されたコピーを開く。',
      scope: 'sample-team-editor-status'
    }
  ],
  lenses: [
    {
      id: 'lens-editor-lifecycle',
      label: 'エディタの保存と公開のライフサイクル',
      rationale: 'SavedとPublishedの状態遷移およびチームページ閲覧者への可視性を検証する',
      origin: 'initial',
      status: 'active'
    }
  ],
  gaps: [
    {
      id: 'gap-visibility-check',
      kind: 'unsupported_claim',
      lensId: 'lens-editor-lifecycle',
      question: 'Savedと表示された変更はチームページ閲覧者に見えるか？',
      triggerRefs: ['task:goal', 'claim-saved-draft-only'],
      whyItMatters: '利用者が最も知りたいチームページ閲覧者への可視性を確認するため',
      importance: 'required',
      claimIds: ['claim-saved-draft-only'],
      probeIds: ['probe-guide-inspection']
    }
  ],
  probes: [
    {
      id: 'probe-guide-inspection',
      gapIds: ['gap-visibility-check'],
      method: 'corroboration',
      question: 'editor-guide.mdの記述によりSavedとPublishedの挙動を確認する',
      requiredCapability: 'document_reading',
      sourceGroups: ['draft-editor-doc'],
      successCondition: 'Savedが下書き保存であり、チームページに公開されるにはPublishedが必要であることが明記されていること',
      refutationCondition: 'Savedによって直接チームページに反映されると明記されていること',
      inconclusiveCondition: '記載がないか曖昧であること'
    }
  ],
  assessments: [
    {
      claimId: 'claim-saved-draft-only',
      evidenceIds: ['evidence-editor-guide'],
      verdict: 'supports',
      scopeMatched: true,
      reason: 'editor-guide.mdにSaved means the draft revision has been stored in the workspaceとある一方、チームページで利用可能になるのはPublished means a published copy was created from a saved revision and is available on the team pageと明記されているため。'
    },
    {
      claimId: 'claim-published-copy-visible',
      evidenceIds: ['evidence-editor-guide'],
      verdict: 'supports',
      scopeMatched: true,
      reason: 'editor-guide.mdにPublished means a published copy was created from a saved revision and is available on the team pageと記述されているため。'
    },
    {
      claimId: 'claim-further-save-no-overwrite',
      evidenceIds: ['evidence-editor-guide'],
      verdict: 'supports',
      scopeMatched: true,
      reason: 'editor-guide.mdにSaving further edits does not replace the existing published copyと記述されているため。'
    },
    {
      claimId: 'claim-preview-default',
      evidenceIds: ['evidence-editor-guide'],
      verdict: 'supports',
      scopeMatched: true,
      reason: 'editor-guide.mdにThe editor preview opens the most recently published copy by defaultと記述されているため。'
    }
  ],
  resolutions: [
    {
      gapId: 'gap-visibility-check',
      reason: 'supported',
      evidenceIds: ['evidence-editor-guide'],
      explanation: 'editor-guide.mdの記述に基づき、Savedのみではワークスペース内保存に留まり、チームページ閲覧者に見えるようになるにはPublishedが必要であることが確認された。'
    }
  ]
};

const envelope = {
  binding: context.binding,
  proposal: proposal
};

fs.writeFileSync('.session/proposal.json', JSON.stringify(envelope, null, 2), 'utf8');
console.log('wrote proposal.json');
"
wrote proposal.json

